import{_ as a,o as d,c as o,ak as e}from"./chunks/framework.DKi5cyCJ.js";const h=JSON.parse('{"title":"USB 驱动","description":"四种传输、枚举、端点、CDC 与 HID，以及虚拟串口和 UART 桥的差别","frontmatter":{"title":"USB 驱动","description":"四种传输、枚举、端点、CDC 与 HID，以及虚拟串口和 UART 桥的差别","date":"2026-10-21T00:00:00.000Z"},"headers":[],"relativePath":"pages/blog/2026-10-21-USB驱动.md","filePath":"pages/blog/2026-10-21-USB驱动.md"}'),l={name:"pages/blog/2026-10-21-USB驱动.md"};function r(s,t,i,c,n,b){return d(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="usb-驱动" tabindex="-1">USB 驱动 <a class="header-anchor" href="#usb-驱动" aria-label="Permalink to &quot;USB 驱动&quot;">​</a></h1><blockquote><p>系列目录：<a href="/pages/blog/2026-10-20-嵌入式驱动面试手册.html">嵌入式驱动面试手册</a></p></blockquote><p>USB 由主机轮询。设备不能主动开传，只能响应。一个主机最多 127 个设备，拓扑是集线器组成的星形。嵌入式多数做 Device；带 OTG 的型号才能切换 Host。</p><table tabindex="0"><thead><tr><th>传输</th><th>特点</th><th>典型用途</th></tr></thead><tbody><tr><td>控制</td><td>EP0 必须有，可靠</td><td>枚举、标准请求</td></tr><tr><td>批量</td><td>可靠，没有固定周期</td><td>CDC、U 盘</td></tr><tr><td>中断</td><td>有最大服务间隔，数据量小</td><td>HID</td></tr><tr><td>等时</td><td>保证带宽，允许丢包</td><td>音频、视频</td></tr></tbody></table><p>STM32 许多型号没有等时输入端点。做音频前先查手册。</p><h2 id="枚举" tabindex="-1">枚举 <a class="header-anchor" href="#枚举" aria-label="Permalink to &quot;枚举&quot;">​</a></h2><div class="blog-flow"><div class="blog-flow-row"><div class="blog-flow-node">复位</div><div class="blog-flow-arrow">→</div><div class="blog-flow-node">读设备描述符前 8 字节</div><div class="blog-flow-arrow">→</div><div class="blog-flow-node">SetAddress</div><div class="blog-flow-arrow">→</div><div class="blog-flow-node">完整描述符</div><div class="blog-flow-arrow">→</div><div class="blog-flow-node accent">SetConfiguration</div></div></div><p>描述符从外到内是：设备 → 配置 → 接口 → 端点。多字节字段是小端。控制传输是 SETUP，后面可以有 DATA，最后是 STATUS。枚举失败时先看停在哪一步，再核对描述符长度和 EP0 最大包长。</p><p>端点是主机能寻址的通道，不只是一块缓冲区。EP0 双向，负责枚举。CDC 虚拟串口通常还要一个中断 IN（通知）和一对批量 IN/OUT。HID 的关键是报告描述符，主机按周期读中断端点。一个配置里有多套功能时，用 IAD 把同一功能的接口绑在一起。</p><h2 id="和-uart-桥的差别" tabindex="-1">和 UART 桥的差别 <a class="header-anchor" href="#和-uart-桥的差别" aria-label="Permalink to &quot;和 UART 桥的差别&quot;">​</a></h2><p>桥接芯片那边有真实波特率。原生 USB CDC 里，主机设置的 115200 通常只是形式参数，实际吞吐看全速 12 Mbit/s 和批量端点。系统自带 CDC 驱动，一般不用装桥接芯片的驱动。</p><p><a href="/pages/blog/2026-10-20-嵌入式驱动面试手册.html">返回目录</a></p>',12)])])}const f=a(l,[["render",r]]);export{h as __pageData,f as default};
